import { EcdCenterStatus } from '../../../common/domain';
import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  IsEnum,
  IsIn,
  IsInt,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  Max,
  MaxLength,
  Min,
  MinLength,
} from 'class-validator';
import { MIN_START_YEAR, NCDA_TYPE_CODES, NcdaTypeCode } from '../ecd-code';

/**
 * Register a new ECD facility. The NCDA code is generated by the server from
 * the village's MINALOC code, the type letter, the start year and the next
 * per-village number; clients never supply it.
 */
export class CreateCenterDto {
  @ApiProperty({ example: 'Kigali ECD Center', minLength: 1, maxLength: 200 })
  @IsString()
  @MinLength(1)
  @MaxLength(200)
  name: string;

  @ApiProperty({ format: 'uuid', description: 'Village (must carry a MINALOC code)' })
  @IsUUID()
  villageId: string;

  @ApiProperty({
    enum: NCDA_TYPE_CODES,
    description:
      'NCDA type letter: A Daycare, B Home-based, C Community-based, D School-based, E Model ECD',
  })
  @IsIn(NCDA_TYPE_CODES as unknown as string[])
  ncdaTypeCode: NcdaTypeCode;

  @ApiProperty({
    example: 2020,
    minimum: MIN_START_YEAR,
    description: 'Year the facility started providing services',
  })
  @Type(() => Number)
  @IsInt()
  @Min(MIN_START_YEAR)
  @Max(2100)
  startYear: number;

  @ApiPropertyOptional({ example: '+250788123456', maxLength: 30 })
  @IsOptional()
  @IsString()
  @MaxLength(30)
  phone?: string;

  @ApiPropertyOptional({ example: 40, minimum: 0 })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(0)
  capacity?: number;

  @ApiPropertyOptional({ example: -1.9441 })
  @IsOptional()
  @Type(() => Number)
  @IsNumber()
  latitude?: number;

  @ApiPropertyOptional({ example: 30.0619 })
  @IsOptional()
  @Type(() => Number)
  @IsNumber()
  longitude?: number;

  @ApiPropertyOptional({ enum: EcdCenterStatus, enumName: 'EcdCenterStatus' })
  @IsOptional()
  @IsEnum(EcdCenterStatus)
  status?: EcdCenterStatus;
}
